\label{prop:wrapped_orth}
Let polynomials ${\bm Q}_{{\bm j}, {\bm k}, m}^n$ of $d_1+d_2$ variables be defined by
\begin{equation}\label{eq:wrapOP}
   {\bm Q}_{{\bm j}, {\bm k}, m}^n({\bm x}, {\bm y}) = {\bm R}_{{\bm j},n-m}^{(m)}({\bm y}) [\rho({\bm y})]^m {\bm P}_{{\bm k},m}\left(\frac{{\bm x}}{\rho({\bm y})}\right),  
\end{equation}
where $0 \le m \le n$, $|{\bm k}| = m$ with ${\bm k} \in {\mathbb N}_0^{d_1}$, and $|{\bm j}| = n-m$ with ${\bm j} \in {\mathbb N}_0^{d_2}$. 
Then the collection $\left\{  {\bm Q}_{{\bm j}, {\bm k}, m}^n: |{\bm k}| = m,\,  |{\bm j}| = n-m, 0 \le m \le n\right\}$ is an orthogonal basis 
of the space ${\mathcal V}_n\big(\Omega_1^{d_1}  \rtimes \Omega_2^{d_2}, {\bm W}^{\Omega_1\rtimes \Omega_2}\big)$.

For $\mu > - \frac12$, ${\boldsymbol{\kappa}} \in {\mathbb R}^{d_2}$ with ${\kappa}_j > -1$, $1 \le j \le d_2$, define 
\begin{equation} \label{eq:Qbasis}
 \bm Q_{\bm j, \bm k, m}^n(\bm x,\bm y) = \bm T_{\bm j, n-m}^{({\boldsymbol{\kappa}}, \alpha+2m)}(\bm y) (1-|\bm y|)^m 
      \bm B_{\bm k, m}^\mu \left(\frac{\bm x}{1-|\bm y| }\right),
\end{equation}
where $\alpha = 2 \mu + d_1-1$. Then 
$\{\bm Q_{\bm j, \bm k, m}^n: |\bm k| = m, \, |\bm j| = n-m, \, 0 \le m  \le n, \, \bm k \in {\mathbb N}_0^{d_1}, \, \bm j \in {\mathbb N}_0^{d_2}\}$ 
is an orthogonal basis of ${\mathcal V}_n\big({\mathbb B}^{d_1} \rtimes \triangle^{d_2}, \bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}\big)$. 
Moreover, the squared norm of $\bm Q_{\bm j, \bm k, m}^n$ is given by 
\begin{equation} \label{eq:Q_OPNorm}
   \bm h_{\bm j, \bm k, m}^{n; \mu,{\boldsymbol{\kappa}}}                                                                          

       = \frac{(2\mu+d_1)_{2m}} {(|{\boldsymbol{\kappa}}|+ 2\mu + d_1 + d_2)_{2m}}\bm h_{\bm k,m}^{\mu, {\mathbb B}}  
       \bm h_{\bm j,m}^{({\boldsymbol{\kappa}}, {\alpha}+2m), \triangle}. 
\end{equation}

For $0 \le m \le n$, $\bm j \in {\mathbb N}_0^{d}$, $x \in [-1,1]$ and $\bm y \in {\mathbb R}^d$, define 
\begin{equation} \label{eq:Qbasis_d1=1}
 \bm Q_{\bm j, m}^n(x,\bm y) = \bm T_{\bm j, n-m}^{({\boldsymbol{\kappa}}, 2\mu+2m)}(\bm y) (1-|\bm y|)^m 
      C_m^\mu \left(\frac{x}{1-|\bm y| }\right). 
\end{equation}
Then the collection $\{\bm Q_{\bm j, m}^n:   |\bm j| = n-m, \, 0 \le m  \le n,   \, \bm j \in {\mathbb N}_0^{d}\}$ 
is an orthogonal basis of ${\mathcal V}_n\big({\mathbb B}^1 \rtimes \triangle^{d}, \bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}\big)$. 
Moreover, the squared norm of ${\bm Q}_{\bm j, m}^n$ is given by                           
\begin{equation} \label{eq:Q_OPNorm_d1=1}
   \bm h_{\bm j, m}^{n; \mu,{\boldsymbol{\kappa}}}  = {\langle} \bm Q_{\bm j, m}^n, \bm Q_{\bm j, m}^n {\rangle}_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}  

       = \frac{(2\mu+1)_{2m}} {(|{\boldsymbol{\kappa}}|+ 2\mu + d+1)_{2m}} h_m^\mu \bm h_{\bm j, m}^{({\boldsymbol{\kappa}}, 2m+2\mu), \triangle}.
\end{equation}

Let ${\boldsymbol{\kappa}} =({\kappa}_1,\ldots, {\kappa}_d)$, ${\kappa}_i \ge - 1/2$ and $\mu \ge 0$. Then, for $(x, \bm y)$ and $(u, \bm v)$ in 
${\mathbb B}^1 \rtimes \triangle^{d}$,
\begin{align} \label{eq:Pn_d=1}
 \bm P_n^{1,d}  \left(\bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}; (x,\bm y), (u, \bm v)\right) 
 & = c_{\mu,{\boldsymbol{\kappa}}} \int_{[-1,1]^{d+2}} Z_{2n}^{|{\boldsymbol{\kappa}}| + 2\mu +d}  \big(\eta(x, \bm y, u, \bm v; \bm t) \big) \\
  &  \times \prod_{i=1}^{d} (1-t_i^2)^{{\kappa}_i-\frac12}  (1-t_{d+1}^2)^{\mu - 1}(1-t_{d+2}^2)^{\mu - 1} \mathrm{d} \bm t, 
   \notag
\end{align}
where $c_{\mu,{\boldsymbol{\kappa}}} =  c_{{\kappa}_1}\cdots  c_{{\kappa}_{d-1}} (c_{\mu-\frac12})^{2} $, and
\begin{align}\label{eq:eta()}
 \eta(x, \bm y, u, \bm v; \bm t)  = &  \sqrt{y_1 v_1} \, t_1+ \ldots + \sqrt{y_d v_d} \,t_{d} 
    + \frac12 \sqrt{1-|\bm y|+x} \sqrt{1-|\bm v|+u}\,t_{d+1} \\
   & + \frac12 \sqrt{1-|\bm y| - x} \sqrt{1-|\bm v|-u} \,t_{d+2}. \notag
\end{align}
Moreover,  the identity holds under the limit \eqref{eq:limitInt} if one or more ${\kappa}_i= -\frac12$ and/or $\mu = 0$.

\label{thm:addition_BT}
Let $\mu \ge 0$ and ${\kappa}_i \ge -\frac12$, $1\le i \le d_2$. For $(\bm x, \bm y)$ and $(\bm u, \bm v) \in {\mathbb B}^{d_1} \! \rtimes \triangle^{d_2}$,
\begin{align}\label{eq:addition}
  \bm P_n^{d_1,d_2}  \big(\bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle},  (\bm x, \bm y), (\bm u, \bm v) \big) 
    = & \, c_{\mu,{\boldsymbol{\kappa}}} \int_{[-1,1]^{d_2+2}}   Z_{2n}^{|{\boldsymbol{\kappa}}| + 2\mu + d_1+d_2-1}
    \big( \xi(\bm x, \bm y, \bm u, \bm v; \bm s, \bm t)\big) \notag \\
   &\times \prod_{i=1}^{d_2} (1-t_i^2)^{{\kappa}_i-\frac12}  \prod_{i=1}^2 (1-s_i^2)^{\mu - 1}  \mathrm{d} \bm t\, \mathrm{d} \bm s,
\end{align}
where $c_{\mu, {\boldsymbol{\kappa}}} =  c_{{\kappa}_1}\cdots c_{{\kappa}_{d_2}} (c_{\mu-\frac12})^{2} $ and
\begin{align*}
& \xi(\bm x, \bm y, \bm u, \bm v; \bm s, \bm t) =  \sqrt{y_1 v_1} \, t_1 + \cdots + \sqrt{y_{d_2} v_{d_2}} \, t_{d_2}  \\ 
   & \quad + \sqrt{\frac12 \left( {\langle} \bm x, \bm u {\rangle}+(1-|\bm y|)(1-|\bm v|) +  s_1 \sqrt{(1-|\bm y|)^2-\|\bm x\|^2}\sqrt{(1-|\bm v|)^2-\|\bm u\|^2} \right)} \, s_2.
\end{align*}
Moreover, \eqref{eq:addition} holds under the limit \eqref{eq:limitInt} if one or more ${\kappa}_i= -\frac12$ and/or $\mu = 0$.

The integral identity is deduced from \eqref{eq:P=IntP} and \eqref{eq:Pn_d=1} with $\mu$ replaced by $\mu + \frac{d-1}2$, and the 
integrand becomes 
\begin{align*}
&  \xi(\bm x, \bm y, \bm u, \bm v; \bm s, \bm t) = \eta \big(\zeta (\bm x,\bm y,  \bm u,\bm v; s_2),  
\bm y, 1-|\bm v|, \bm v;  \bm t \big)  \\ 
\qquad  &  = \sqrt{y_1 v_1} \, t_1 + \cdots + \sqrt{y_d v_d} \, t_d + \frac12 \sqrt{1-|\bm y| + 
     \zeta(\bm x, \bm y, \bm u, \bm v; s)} \sqrt{2 (1-|\bm v|)}\, t_{d+1}
\end{align*}
as the last term in \eqref{eq:eta()} becomes zero when $u = 1-|\bm v|$, which simplifies to the stated formula for
$\xi(\bm x, \bm y, \bm u, \bm v; \bm s, \bm t)$ after setting $s= s_1$ and $t_{d+1} = s_2$.

\label{lem:translateT}
Let $g \in L^1([-1,1],w_{{\alpha}, - \frac12})$. Then, for each 
$Q_n \in {\mathcal V}_n \big({\mathbb B}^{d_1} \!\rtimes \triangle^{d_2}, \bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}\big)$, 
\begin{equation}\label{eq:FHformula}
     \int_{{\mathbb B}^{d_1} \!\rtimes \triangle^{d_2}}  T^{(\mu,{\boldsymbol{\kappa}})} g (\bm x, \bm y) Q_n (\bm y) \bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}
       ({\bm x}, \bm y) \mathrm{d} \bm x \mathrm{d} \bm y  = 
      \Lambda_n^{({\alpha},-\frac12)} (g) Q_n(\bm x),
\end{equation}
where ${\alpha} = |{\boldsymbol{\kappa}}| + 2\mu + d_1+d_2-1$ and 
$$
 \Lambda_n^{({\alpha}, -\frac12)} (g) =  c_{{\alpha}, -\frac12} \int_{-1}^1 g(t) \frac{P_n^{({\alpha}, -\frac12)}(t)}{P_n^{({\alpha},-\frac12)}(1)} w_{{\alpha},-\frac12}(t)\mathrm{d} t.

$$
Furthermore, for $1\le p \le \infty$ and $\bm x \in {\mathbb B}^{d_1} \rtimes \triangle^{d_2}$, 
\begin{equation}\label{eq:Tbd}
  \left \| T^{(\mu,{\boldsymbol{\kappa}})} g (\bm x, \cdot)\right\|_{L^p({\mathbb B}^{d_1} \! \rtimes \triangle^{d_2}, \bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle})} \le \|g \|_{L^p([-1,1],w_{{\alpha},-\frac12})}.
\end{equation}

\label{thm:Young}
Let $p,q,r \ge 1$ and $p^{-1} = r^{-1}+q^{-1}-1$. For $f \in L^q({\mathbb B}^{d_1} \!\rtimes \triangle^{d_2}, 
 \bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle})$ and $g \in L^r([-1,1]; w_{{\alpha},-\frac12})$ with ${\alpha} = |{\boldsymbol{\kappa}}| + 2\mu + d_1+d_2-1$,
\begin{equation} \label{eq:Young}
  \|f \ast g\|_{L^p ({\mathbb B}^{d_1}\rtimes \triangle^{d_2}, \bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle})} 
     \le \|f\|_{L^q({\mathbb B}^{d_1}\rtimes \triangle^{d_2}, \bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle})}\|g\|_{L^r( [-1,1]; w_{{\alpha},-\frac12})}.
\end{equation}

\label{thm:cesaro}
Let $\mu \ge 0$ and ${\kappa}_i \ge -\frac12$, $1 \le i\le d_2$, and ${\alpha} = |{\boldsymbol{\kappa}}| + 2\mu + d_1+d_2-1$. 
Then Ces\`aro $(C,\delta)$ means of the Fourier orthogonal expansion
for $\bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}$ on ${\mathbb B}^{d_1} \!\rtimes \triangle^{d_2}$ satisfy the following: 
\begin{enumerate}
\item If $\delta \ge {\alpha}+ \frac32$, then $S_n^\delta\big(\bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}; f\big)$ is a nonnegative operator;
\item If $\delta > {\alpha} +\frac12$, then for $n= 0,1,2,\ldots$,
$$
    \left \|S_n^\delta\big( \bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle};  f\big)\right \|_{L^p({\mathbb B}^{d_1}\rtimes \triangle^{d_2},
      \bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle})} \le c\,  \|f\|_{L^p({\mathbb B}^{d_1}\rtimes \triangle^{d_2},\bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle})}, \quad 1 \le p \le \infty.
$$
\end{enumerate}
In particular, $S_n^\delta\big( \bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle};  f\big)$ converges to $f$ in 
$L^p\big({\mathbb B}^{d_1} \rtimes \triangle^{d_2}, \bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}\big)$ if $\delta > {\alpha} + \frac12$.

For ${\gamma} > - d_1$, let ${\alpha} = {\gamma} + d_1 -1$. Define                                                                                                         



\begin{equation} \label{eq:QbasisV0}
 {\mathsf Q}_{\bm j, \ell, m}^n(\bm x,\bm y) = \bm T_{\bm j, n-m}^{({\boldsymbol{\kappa}}, \alpha+2m)}(\bm y) (1-|\bm y|)^m 
      {\mathsf Y}_{\ell}^m \left(\frac{\bm x}{1-|\bm y|}\right). 
\end{equation}
Then $\{{\mathsf Q}_{\bm j, \ell, m}^n: |\bm j| = n-m, \, 1 \le \ell \le \dim {\mathcal H}_m^{d_1}, \, 0 \le m  \le n, \bm j \in {\mathbb N}_0^{d_2}\}$ 
is an orthogonal basis of ${\mathcal V}_n({\mathbb S}^{d_1-1}\!\rtimes \triangle^{d_2}, {\mathsf W}_{{\gamma}, {\boldsymbol{\kappa}}}^{{\mathbb S}\rtimes \triangle})$. Moreover, the 
squared norm of ${\mathsf Q}_{\bm j, \ell, m}^n$ 
is given by 
\begin{equation} \label{eq:Q_V0Norm}
   {\mathsf h}_{m,n}^{{\gamma},{\boldsymbol{\kappa}}}                                                                        
       =   \frac{\bm b^\triangle_{({\boldsymbol{\kappa}},\alpha)}}{\bm b^\triangle_{({\boldsymbol{\kappa}}, \alpha + 2m)}} \bm h_{\bm j,m}^{({\boldsymbol{\kappa}}, {\alpha}+ 2m), \triangle}
       = \frac{({\gamma} +d_1)_{2m}} {(|{\boldsymbol{\kappa}}|+ {\gamma} + d_1 + d_2)_{2m}} \bm h_{\bm j,m}^{({\boldsymbol{\kappa}}, {\alpha}+ 2m), \triangle}.  
\end{equation}

\label{thm:additionV0}
Let $d_1 \ge 2$ and ${\kappa}_1,\ldots, k_{d_2} \ge -\frac12$. Then 
\begin{align}\label{eq:additionV0}
  {\mathsf P}_n  \big({\mathsf W}_{-1, {\boldsymbol{\kappa}}}^{{\mathbb S}\rtimes \triangle},  (\bm x, \bm y), (\bm u, \bm v) \big) 
    = & \, {\mathsf c}_{-1,{\boldsymbol{\kappa}}} \int_{[-1,1]^{d_2+1}} Z_{2n}^{|{\boldsymbol{\kappa}}| + d_1+d_2-2}
    \big( \xi_0(\bm x, \bm y, \bm u, \bm v; s, \bm t)\big)  \\
   & \times \prod_{i=1}^{d_2} (1-t_i^2)^{{\kappa}_i-\frac12}  (1-s^2)^{\frac{d_1-2}{2} - 1}  \mathrm{d} \bm t\, \mathrm{d} s,\notag
\end{align}
where $ {\mathsf c}_{-1,{\boldsymbol{\kappa}}} = c_{{\kappa}_1} \cdots c_{{\kappa}_{d_2}} c_{\frac{d_1-3}{2}}$ and 
\begin{align*}
& \xi_0(\bm x, \bm y, \bm u, \bm v; s, \bm t) =  \sqrt{y_1 v_1} \, t_1 + \cdots + \sqrt{y_{d_2} v_{d_2}} \, t_{d_2} 
+ \sqrt{\tfrac12 \left[ {\langle} \bm x, \bm u {\rangle}+(1-|\bm y|)(1-|\bm v|)\right]} \, s.
\end{align*}
Moreoever, the identity \eqref{eq:additionV0} holds under the limit if one or more ${\kappa}_i = - \frac12$ or $d_1= 2$.

For ${\kappa}_i \ge -\frac12$, $1 \le i \le d$, let $ {\alpha} = |{\boldsymbol{\kappa}}| + d_1+d_2-2$. For $f\in L^1\big({\mathbb S}^{d_1-1}\!\rtimes \triangle^{d_2}\big)$ 
and $g \in L^1([-1, 1], w_{{\alpha}, -\frac12})$, define the pseudo convolution of $f$ and $g$ by
\begin{equation} \label{eq:convolu0}
 f\ast_0 g (\bm x,\bm y) = \int_{{\mathbb B}^{d_1} \! \rtimes \triangle^{d_2}} f(\bm u,\bm v) {\mathsf T}^{{\boldsymbol{\kappa}}} g\big ( (\bm x,\bm y), (\bm u,\bm v) \big)
    {\mathsf W}_{-1, {\boldsymbol{\kappa}}}^{{\mathbb S}\rtimes \triangle} (\bm u, \bm v) \mathrm{d} \sigma(\bm u, \bm v)
\end{equation}
where the operator $g \mapsto {\mathsf T}^{{\boldsymbol{\kappa}}} g$ is defined by 
\begin{align*}
{\mathsf T}^{{\boldsymbol{\kappa}}} g \big ( (\bm x,\bm y), (\bm u,\bm v) \big)
 =  & \, {\mathsf b}_{-1,{\boldsymbol{\kappa}}} \int_{[-1,1]^{d+1}} \int_{-1}^1 g \big( 2 \xi_0(\bm x, \bm y, \bm u, \bm v; s, \bm t)^2-1 \big) \notag \\
   &\times \prod_{i=1}^{d_2} (1-t_i^2)^{{\kappa}_i-\frac12}  (1-s^2)^{\frac{d_1-2}{2} - 1}  \mathrm{d} \bm t\, \mathrm{d} s.
\end{align*}

\label{thm:cesaro_0}
Let ${\kappa}_i \ge -\frac12$, $1 \le i\le d_2$, and ${\alpha} = |{\boldsymbol{\kappa}}| + d_1+d_2-2$. Then Ces\`aro $(C,\delta)$ means of the Fourier orthogonal 
expansion for ${\mathsf W}_{-1, {\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}$ on ${\mathbb S}^{d_1-1}\!\rtimes \triangle^{d_2}$ satisfie the following: 
\begin{enumerate}
\item If $\delta \ge {\alpha}+ \frac32$, then $S_n^\delta\big({\mathsf W}_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb S}\rtimes \triangle}; f\big)$ is a nonnegative operator;
\item If $\delta > {\alpha} +\frac12$, then for $n= 0,1,2,\ldots$,
$$
    \left \|S_n^\delta\big( {\mathsf W}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S}\rtimes \triangle};  f\big)\right \|_{L^p\big({\mathbb S}^{d_1-1}\!\rtimes \triangle^{d_2},{\mathsf W}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S}\rtimes \triangle}\big)} \le 
     \|f\|_{L^p\big({\mathbb S}^{d_1-1}\!\rtimes \triangle^{d_2},{\mathsf W}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S}\rtimes \triangle}\big)}, \qquad 1 \le p \le \infty.
$$
\end{enumerate}
In particular, $S_n^\delta\big( {\mathsf W}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S}\rtimes \triangle};  f\big)$ converges to $f$ in
$L^p\big({\mathbb S}^{d_1-1}\!\rtimes \triangle^{d_2},{\mathsf W}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S}\rtimes \triangle}\big)$ if $\delta > {\alpha} + \frac12$.

For $\mu > -\frac12$, ${\boldsymbol{\kappa}}\in {\mathbb R}^{d_2-1}$ with ${\kappa}_j > -1$, $1 \le j \le d_2-1$, define
\begin{equation} \label{eq:OP_BSig}
 \bm Q_{\bm j, \bm k, m}^n(\bm x,\bm y) = \hat {\bm L}_{\bm j, n-m}^{({\boldsymbol{\kappa}}, \alpha+2m)}(\bm y) |\bm y|^m 
      \bm B_{\bm k, m}^\mu \left(\frac{\bm x}{|\bm y|}\right),
\end{equation}
where $\alpha = 2 \mu + d_1-1$. Then $\{\bm Q_{\bm j, \bm k, m}^n: |\bm k| = m, \, |\bm j| = n-m, \, \bm k \in {\mathbb N}_0^{d_1}, \, \bm j \in {\mathbb N}_0^{d_2}, 0\le m \le n\}$ 
is an orthogonal basis of ${\mathcal V}_n\big({\mathbb B}^{d_1}\!\! \rtimes {\mathbb R}_\Sigma^{d_2}, \bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \Sigma}\big)$. 
Moreover, the squared norm of $\bm Q_{\bm j, \bm k, m}^n$ is given by 
\begin{equation} \label{eq:OP_BSig_Norm}
   \bm h_{\bm j, \bm k, m}^{n; \mu,{\boldsymbol{\kappa}}}                                                                          

       =  (2\mu+d_1)_{2m} \bm h_{\bm k,m}^{\mu, {\mathbb B}}  
       \bm h_{\bm j,m}^{({\boldsymbol{\kappa}}, {\alpha}+2m), \triangle}. 
\end{equation}

\label{prop:Pn_BSig_d1=1}
Let ${\boldsymbol{\kappa}} =({\kappa}_1,\ldots, {\kappa}_d)$, ${\kappa}_i > - 1/2$ and $\mu > 0$. Then, for $(x, \bm y)$ and $(u, \bm v)$ in 
${\mathbb B}^1 \rtimes {\mathbb R}_\Sigma^{d} = [-1,1] \rtimes {\mathbb R}_\Sigma^{d}$,
\begin{align*} 
 & \bm P_n^{1,d} \left(\bm W_{\mu, {\boldsymbol{\kappa}}}^{[-1,1] \rtimes \Sigma}; (x,\bm y), (u, \bm v)\right) 
  = {\bm c}_{\mu,{\boldsymbol{\kappa}}} \int_{[0,\pi]^{d+1}} L_n^{|{\boldsymbol{\kappa}}| + 2\mu +d-1} \big(\eta(x, \bm y, u, \bm v; \bm {\theta}) \big) \\
  & \times \prod_{i=1}^{d-1} j_{{\kappa}_i-\frac12}\big ( \sqrt{y_i v_i} \sin {\theta}_i\big) j_{\mu-\frac12} 
   \Big(\sqrt{\tfrac{|{\bm y}|+x}2} \sqrt{\tfrac{|{\bm v}|+u}{2}} \sin {\theta}_{d} \Big) 
   j_{\mu-\frac12} \Big(\sqrt{\tfrac{|{\bm y}|-x}2} \sqrt{\tfrac{|{\bm v}|-u}{2}} \sin {\theta}_{d+1} \Big) \\
 &\times \exp \left( -\sum_{i=1}^{d-1} \sqrt{y_i v_i} \cos {\theta}_i- \frac12 \sqrt{(|{\bm y}|+x) (|{\bm v}|+u)} \cos {\theta}_{d} - \frac12 \sqrt{(|{\bm y}|-x) (|{\bm v}|-u)} 
 \cos {\theta}_{d+1}\right)\\
  & \times \prod_{i=1}^{d-1} (\sin {\theta}_i)^{{\kappa}_i} (\sin {\theta}_d)^{2\mu-1} (\sin {\theta}_{d+1})^{2\mu-1} \mathrm{d} \bm{{\theta}},
\end{align*}
where ${\bm c}_{\mu,{\boldsymbol{\kappa}}} =  {\bm c}_{{\boldsymbol{\kappa}}, \mu-\frac12, \mu - \frac12}^L$, and
\begin{align}\label{eq:eta()BSig}
 \eta(x, \bm y, u, \bm v; \bm t)  = & |{\bm y}'| + |{\bm y}| +|{\bm v}'| + |{\bm v}| + 2 \sum_{i=1}^{d-1} \sqrt{y_i v_i} \cos {\theta}_i \\
   & +  \sqrt{(|{\bm y}|+x) (|{\bm v}|+u)} \cos {\theta}_{d} + \sqrt{(|{\bm y}|-x) (|{\bm v}|-u)} \cos {\theta}_{d+1}. \notag
\end{align}
